import logging

from .base import UePcServerRunner


class IperfDataTransfer(UePcServerRunner):
    """Iperf Data Transfer"""
    def __init__(self, ue_name, dt_name, dt_protocol, dt_direction, ue_pc_instance, ue_id, ue_ip, ue_type, command_tail,
                 adb_iperf_path=None, app_srv_lte_ip=None, iperf_version=None, analyzer_params=None, verification_delay=10):
        """
        :param ue_pc_instance:
        :param ue_name:
        :param dt_name:
        :param ue_ip:
        :param command_tail:
        :param dt_protocol:
        :param dt_direction:
        :param ue_id:
        :param ue_type:
        :param adb_iperf_path:
        :param app_srv_lte_ip:
        :param iperf_version:
        :param analyzer_params:
        :param verification_delay:
        """
        super(IperfDataTransfer, self).__init__(ue_name=ue_name,
                                                dt_name=dt_name,
                                                dt_protocol=dt_protocol,
                                                dt_direction=dt_direction,
                                                ue_pc_instance=ue_pc_instance,
                                                ue_id=ue_id,
                                                ue_ip=ue_ip,
                                                ue_type=ue_type,
                                                command_tail=command_tail,
                                                app_srv_lte_ip=app_srv_lte_ip,
                                                ue_iperf_adb_dir=adb_iperf_path,
                                                iperf_version=iperf_version,
                                                analyzer_params=analyzer_params,
                                                verification_delay=verification_delay,
                                                local_timestamp=None)
        if 'logger' in analyzer_params:
            self.logger = analyzer_params['logger']
        else:
            self.logger = logging.getLogger('ute_ue')
        self.logger.info("Initialized object {} on UE PC.".format(self.__class__.__name__))
